CREATE TRIGGER IF NOT EXISTS sync_book_reading_journal_version AFTER INSERT ON sync_book_reading_journal BEGIN
 SELECT CASE WHEN NEW.seq>9007199254740991 THEN RAISE(ABORT,'reading sequence exhausted') END;
 INSERT INTO sync_book_reading_versions VALUES(NEW.book_id,NEW.chapter_index,NEW.seq) ON CONFLICT(book_id,chapter_index) DO UPDATE SET seq=excluded.seq;END

CREATE TRIGGER IF NOT EXISTS sync_book_reading_delta_insert AFTER INSERT ON sync_book_reading  BEGIN
 INSERT INTO sync_book_reading_journal(book_id,chapter_index) VALUES(NEW.book_id,NEW.chapter_index);
 DELETE FROM sync_book_reading_hashes WHERE book_id=NEW.book_id AND chapter_index=NEW.chapter_index;
 INSERT INTO sync_book_reading_hash_dirty VALUES(NEW.book_id) ON CONFLICT(book_id) DO NOTHING;
 UPDATE sync_book_reading_meta SET root=NULL WHERE id=1;END

CREATE TRIGGER IF NOT EXISTS sync_book_reading_delta_update AFTER UPDATE ON sync_book_reading WHEN OLD.state_json IS NOT NEW.state_json BEGIN
 INSERT INTO sync_book_reading_journal(book_id,chapter_index) VALUES(NEW.book_id,NEW.chapter_index);
 DELETE FROM sync_book_reading_hashes WHERE book_id=NEW.book_id AND chapter_index=NEW.chapter_index;
 INSERT INTO sync_book_reading_hash_dirty VALUES(NEW.book_id) ON CONFLICT(book_id) DO NOTHING;
 UPDATE sync_book_reading_meta SET root=NULL WHERE id=1;END

CREATE TRIGGER IF NOT EXISTS sync_book_reading_delta_delete AFTER DELETE ON sync_book_reading  BEGIN
 DELETE FROM sync_book_reading_versions WHERE book_id=OLD.book_id AND chapter_index=OLD.chapter_index;
 DELETE FROM sync_book_reading_hashes WHERE book_id=OLD.book_id AND chapter_index=OLD.chapter_index;
 INSERT INTO sync_book_reading_hash_dirty VALUES(OLD.book_id) ON CONFLICT(book_id) DO NOTHING;
 UPDATE sync_book_reading_meta SET root=NULL WHERE id=1;END

CREATE TRIGGER IF NOT EXISTS sync_body_revision_article_body_chunks_update AFTER UPDATE ON article_body_chunks WHEN OLD.article_id IS NOT NEW.article_id OR OLD.chunk_index IS NOT NEW.chunk_index OR OLD.body IS NOT NEW.body BEGIN
      INSERT INTO sync_body_revision(item_id,revision) SELECT NEW.article_id,1 WHERE EXISTS(SELECT 1 FROM articles WHERE id=NEW.article_id)
      ON CONFLICT(item_id) DO UPDATE SET revision=revision+1;
      INSERT INTO sync_body_revision(item_id,revision) SELECT OLD.article_id,1 WHERE OLD.article_id!=NEW.article_id AND EXISTS(SELECT 1 FROM articles WHERE id=OLD.article_id) ON CONFLICT(item_id) DO UPDATE SET revision=revision+1;
    END

